mkdir -p /tmp/w3rB && cat > /tmp/w3rB/build.py <<'EOF'
import json, copy, sys
base = json.load(open('out/w3-rB.workflow.json'))
calc = json.load(open('out/w3-rB.calc.json'))
w = copy.deepcopy(base)
w.pop('agent_config', None)

# (1) start node: calc code node, unchanged code
cn = copy.deepcopy(calc['code_node'])
cn['passthrough_default_transition'] = 'opening'
for t in cn['transitions']:
    if t['target_node'] == '<NEXT NODE>':
        t['target_node'] = 'opening'
assert '<NEXT NODE>' not in json.dumps(cn)
w['nodes']['date_facts_setup'] = cn
w['initial_node'] = 'date_facts_setup'

# (2) account hook: calc hook verbatim + extra logic after it
EXTRA = r'''
try:
    if isinstance(result, dict):
        d = result.get('data')
        prods = d.get('products') if isinstance(d, dict) else None
        if isinstance(prods, list) and prods:
            names = {'credit_card': 'credit card', 'personal_loan': 'personal loan', 'car_loan': 'car loan'}
            keep = []
            for p in prods:
                if not isinstance(p, dict):
                    continue
                ty = str(p.get('type'))
                if ty == 'credit_card' and p.get('card_last4'):
                    p['say_as'] = 'credit card ending ' + str(p.get('card_last4'))
                else:
                    p['say_as'] = names.get(ty, ty.replace('_', ' '))
                keep.append({'product_id': p.get('product_id'), 'say_as': p.get('say_as'), 'past_due': p.get('past_due'),
                             'floor_amount': p.get('floor_amount'), 'deadline': p.get('deadline')})
            try:
                vars['products_json'] = json.dumps(keep)
            except Exception:
                pass
            n = len(keep)
            if n == 1:
                ask = 'Then ask exactly: "Can you make this payment today?"'
            else:
                ask = 'Then ask once whether they can pay all ' + str(n) + ' of them today (for example: "Can you make all these payments today?").'
            d['what_to_do_next'] = ('Identity is verified. Now say you are calling from the collections team about a late payment, then state EVERY product below, '
                                    'one sentence each, in this order, using say_as, past_due and days_late. ' + ask +
                                    ' Use each product\'s own deadline and floor_amount from this result; never compute them. Look every other date up in date_facts.')
        elif isinstance(d, dict):
            d['what_to_do_next'] = 'The account could not be loaded (' + str(d.get('error')) + '). Call get_account once more. If it fails again, say you do not have the account information right now, thank the customer, say goodbye and call close_call with outcome no_promise and reason service_error.'
        else:
            result['data'] = {'ok': False, 'what_to_do_next': 'The account service failed. Call get_account once more. If it fails again, say you do not have the account information right now, thank the customer, say goodbye and call close_call with outcome no_promise and reason service_error.'}
except Exception:
    pass
'''
acc = w['nodes']['account']
for t in acc['tools']:
    if t['function']['name'] == calc['account_tool']:
        t['post_process_code'] = calc['account_post_process_code'] + '\n' + EXTRA
        assert t['post_process_code'].startswith(calc['account_post_process_code'])

# (3) create_promise pre-hook: keep the recorded values inside the rules
CP_PRE = r'''
import json, datetime
try:
    b = config.get('body')
    if isinstance(b, dict):
        pid = str(b.get('product_id'))
        vars['cp_last_pid'] = pid
        vars['cp_adjusted'] = ''
        prods = []
        try:
            prods = json.loads(vars.get('products_json') or '[]')
        except Exception:
            prods = []
        p = None
        for x in prods:
            if isinstance(x, dict) and str(x.get('product_id')) == pid:
                p = x
        HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
        def bd(d):
            return d.weekday() < 5 and d.isoformat() not in HOL
        if p is not None:
            notes = []
            try:
                amt = float(b.get('amount'))
                pd = float(p.get('past_due'))
                if amt > pd:
                    b['amount'] = pd
                    notes.append('amount capped at past_due ' + str(pd))
            except Exception:
                pass
            try:
                today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
                dl = datetime.date.fromisoformat(str(p.get('deadline'))[:10])
                dt = datetime.date.fromisoformat(str(b.get('date')).strip()[:10])
                nd = dt
                if nd < today:
                    nd = today
                k = 0
                while not bd(nd) and k < 20:
                    nd = nd + datetime.timedelta(days=1)
                    k += 1
                if nd > dl:
                    nd = dl
                if nd != dt:
                    b['date'] = nd.isoformat()
                    notes.append('date set to ' + nd.isoformat())
            except Exception:
                pass
            vars['cp_adjusted'] = '; '.join(notes)
except Exception:
    pass
'''
for t in acc['tools']:
    if t['function']['name'] == 'create_promise':
        t['pre_process_code'] = CP_PRE
        post = t['post_process_code']
        post = post.replace("""            d['what_to_do_next'] = 'RECORDED' + (' for ' + pid if pid else '') + '.""",
                            """            adj = ''
            try:
                adj = str(vars.get('cp_adjusted') or '')
            except Exception:
                adj = ''
            d['what_to_do_next'] = 'RECORDED' + (' for ' + pid if pid else '') + ((' (recorded values: ' + adj + '; tell the customer this exact value)') if adj else '') + '.""")
        assert 'cp_adjusted' in post
        t['post_process_code'] = post

DATE_RULE = "Never compute a date yourself. Look every date up in DATE FACTS: a named weekday via WEEKDAY WORDS, whether a day is a business day and the next business day via CALENDAR, deadlines and attempt dates via the anchor lines."
for k in ('third_party', 'account'):
    tm = w['nodes'][k]['task_message']
    assert DATE_RULE in tm and '{{date_facts}}' in tm, k

json.dump(w, open('out/w3-rB.workflow.json', 'w'), indent=1)
print('ok', list(w['nodes']))
